import SideNav, { SideNavCategory, SideNavItem, SideNavSection } from ".";

const meta: Meta<typeof SideNav> = {
  id: "Components/SideNav",
  title: "Components/Side Navigation",
  component: SideNav,
  argTypes: {
    open: { control: false },
  },
};

export default meta;
type Story = StoryObj<typeof SideNav>;

export const Temporary: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: (args) => {
    const [open, setOpen] = useState(false);
    const [page, setPage] = useState("page1");
    const [theme, setTheme] = useState<ThemeMode>("light");
    const navigateTo = (page: string) => {
      setPage(page);
      setOpen(false);
    };
    return (
      <div>
        <RadioGroup
          row
          value={theme}
          onChange={(e, value) => setTheme(value)}
          style={{ marginBottom: 16 }}
        >
          <Radio value="light" label="light" />
          <Radio value="dark" label="dark" />
        </RadioGroup>
        <Button onClick={() => setOpen(true)}>Open</Button>
        <SideNav
          aria-label="Main Navigation"
          theme={theme}
          open={open}
          onClose={() => setOpen(false)}
          title="Menu"
          {...args}
        >
          <Typography variant="h2" style={{ paddingLeft: "1rem" }}>
            SideNav
          </Typography>
          <SideNavSection style={{ flex: 1 }}>
            <SideNavItem
              selected={page === "page1"}
              onSelected={() => navigateTo("page1")}
            >
              page 1
            </SideNavItem>
            <SideNavItem
              disabled
              selected={page === "page2"}
              onSelected={() => navigateTo("page2")}
            >
              page 2
            </SideNavItem>
            <SideNavItem
              selected={page === "page3"}
              onSelected={() => navigateTo("page3")}
            >
              page 3
            </SideNavItem>
          </SideNavSection>
          <Divider inset />
          <SideNavSection>
            <SideNavItem
              href="goto.airbus.corp/design-system"
              onSelected={action("onSelected")}
            >
              External Link 1
              <Launch />
            </SideNavItem>
            <SideNavItem
              href="goto.airbus.corp/swe-guidelines"
              onSelected={action("onSelected")}
            >
              External Link 2
              <Launch />
            </SideNavItem>
          </SideNavSection>
        </SideNav>
      </div>
    );
  },
};

